\newcommand{\operatorname{arcosh} }{\mathop{\rm arcosh}\nolimits}
\newcommand{\operatorname{artanh} }{\mathop{\rm artanh}\nolimits}
\newcommand{\operatorname{sech} }{\mathop{\rm sech}\nolimits}
\newcommand{\operatorname{csch} }{\mathop{\rm csch}\nolimits}
\newcommand{\coth}{\mathop{\rm coth}\nolimits}
\newcommand{\operatorname{arsech} }{\mathop{\rm arsech}\nolimits}
\newcommand{\operatorname{arcsch} }{\mathop{\rm arcsch}\nolimits}
\newcommand{\operatorname{arcoth} }{\mathop{\rm arcoth}\nolimits}$

For instance, let's show that

$$
\dfrac{\textrm{d}}{\textrm{d}x}(\operatorname{arsinh} {x}) = \dfrac{1}{\sqrt{x^2+1}}.
$$

Recall that

$$
\operatorname{arsinh} {x} = \ln\big(x+\sqrt{x^2+1}\big).
$$

Differentiating using the chain rule, we get

$$
\begin{aligned}\frac{\text{d}}{\text{d}x}(\operatorname{arsinh}⁡x) & =\frac{\text{d}}{\text{d}x}(\operatorname{ln}⁡(x+\sqrt{{x}^{2}+1})) \\  & =\frac{1}{x+\sqrt{{x}^{2}+1}}\cdot (x+\sqrt{{x}^{2}+1})^{′} \\  & =\frac{\left(1+\frac{x}{\sqrt{{x}^{2}+1}}\right)}{x+\sqrt{{x}^{2}+1}} \\  & =\frac{\sqrt{{x}^{2}+1}+x}{\sqrt{{x}^{2}+1}(x+\sqrt{{x}^{2}+1})} \\  & =\frac{\cancel{x+\sqrt{{x}^{2}+1}}}{\sqrt{{x}^{2}+1}\cancel{(x+\sqrt{{x}^{2}+1})}} \\  & =\frac{1}{\sqrt{{x}^{2}+1}}.\end{aligned}
$$

Similarly, we can obtain the other formulas.

